1-54e3-8e75-e75ffbdaecfb", "version": "01.00.000"}, "dimension": "time", "factor": "0.00011415525114155251", "target_unitgroup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "version": "01.00.000"}}], "expected": {"action_count": 6, "amount_field_count": 16, "audit_count": 8, "batch_count": 1, "derivative_target_count": 6, "exchange_count": 8, "flow_count": 3, "flowproperty_count": 0, "process_count": 3, "text_action_count": 1, "unrelated_exchange_count": 3}, "plan_sha256": "3ed37f87d621a03237a3a0d004bf00403b3fbba292beebf0ea5bafadb1e276d5", "schema_version": "dataset-alias-plan.v2", "source_alias": {"id": "bd69e542-6a50-524c-8d04-195b1ec23150", "sha256": "458d10de07aa8a2a2cb84d264b991edcbc92d1e0d16fc51064412a76bea132ed", "version": "00.00.001"}, "source_evidence": {"cohort_sha256": "e818cd161bbf48651973f3d93e8ded448ae4be3eb29835d943b8157ed8a58a55", "declared_source_unitgroup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "sha256": "2f2a83c829ffaea06cef8e337f81319b686e05e683edae521016168393c699d4", "version": "01.00.000"}, "exchange_count": 8, "expected_cohort_sha256": "e818cd161bbf48651973f3d93e8ded448ae4be3eb29835d943b8157ed8a58a55", "original_source_unit": "hr", "sha256": "1ba7a33399e9f45613d3bcdd27270182d7164b6e2e61f0de2592116b38d39d24", "source_flowproperty": {"id": "bd69e542-6a50-524c-8d04-195b1ec23150", "sha256": "8008aaa69fd0b0aa30bb625b8929a1e0e25184e68101ce121394201dd2f4ebaa", "version": "00.00.001"}}, "target_snapshots": {"flowproperty": {"id": "da11d28f-4db8-51eb-b3a9-8784b26771e6", "sha256": "22a048dc39905cbd8f614af04cfe86145eb3d5c98f2ffad42a9f933baeebc8a1", "version": "01.00.000"}, "unitgroup": {"id": "49ce0c2f-2241-54e3-8e75-e75ffbdaecfb", "sha256": "2f2a83c829ffaea06cef8e337f81319b686e05e683edae521016168393c699d4", "version": "01.00.000"}}, "target_visibility": "owner_draft", "text_actions": [{"after_text": "1.0 hr Fixture unit 1", "before_text": "1.0 a Fixture unit 1", "id": "b20c0de0-0000-4000-8000-000000000001", "source_exchange_number": "730000", "table": "processes", "version": "00.00.001"}]}, "project_ref": "qgzvkongdjqiiamzbbts", "request_id": "fcfbc113-8d7e-575c-a7f3-ba5abfbf2265", "schema_version": "dataset-alias-execution-preflight.v2", "target_visibility": "owner_draft"}$wire$::jsonb as request;

create temp table v2_actor as
  select 'c536ee37-64ab-427b-b7e3-4e2bb4fdffb7'::uuid as user_id, 'fixture-owner@example.invalid'::text as email;

create or replace function pg_temp.as_actor(p_actor uuid default null, p_email text default null)
returns void language plpgsql as $$
begin
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  perform set_config('request.jwt.claim.sub',
    coalesce(p_actor, (select user_id from v2_actor))::text, true);
  perform set_config('request.jwt.claim.email',
    coalesce(p_email, (select email from v2_actor)), true);
end
$$;

create or replace function pg_temp.gate_projection(p_result jsonb)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'expected_sha256', p_result->>'expected_sha256',
    'observed_sha256', p_result->>'observed_sha256',
    'status', p_result->>'status',
    'captured_at', p_result->>'captured_at')
$$;

create or replace function pg_temp.admit_request(p_token text, p_proof text, p_gates jsonb)
returns jsonb language sql immutable as $$
  select jsonb_build_object(
    'schema_version', 'dataset-alias-execution-admit.v2',
    'request_id', 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265',
    'preflight_token', p_token,
    'preflight_proof_sha256', p_proof,
    'gate_results', p_gates)
$$;

-- ================================================================================================
-- 1. Refusals before anything is admitted.
-- ================================================================================================
select set_config('request.jwt.claim.sub', '', true);
select set_config('request.jwt.claim.role', '', true);
select set_config('request.jwt.claim.email', '', true);
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire))->>'code'),
  'AUTH_REQUIRED',
  'the protected preflight refuses an unauthenticated call'
);
select is(
  (api.cmd_dataset_alias_execution_admit_v2_guarded(jsonb_build_object('schema_version', 'dataset-alias-execution-admit.v2'))->>'code'),
  'AUTH_REQUIRED',
  'the protected admission refuses an unauthenticated call'
);

select pg_temp.as_actor('22222222-2222-4222-8222-222222222222');
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire))->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_ACTOR_MISMATCH',
  'a request bound to another actor is refused'
);

select pg_temp.as_actor(null, 'another-owner@example.invalid');
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire))->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_ACTOR_MISMATCH',
  'a request whose actor email is not the authenticated email is refused'
);

select pg_temp.as_actor();
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded(
     jsonb_set((select request from v2_wire), '{plan,source_evidence}',
       ((select request from v2_wire) #> '{plan,source_evidence}') - 'source_flowproperty')
   )->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_INVALID_PLAN',
  'a plan edited to drop the source flow property snapshot no longer matches its signed digest'
);
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded(
     jsonb_set((select request from v2_wire), '{plan,source_evidence,source_flowproperty,sha256}', '"not-a-digest"'::jsonb)
   )->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_INVALID_PLAN',
  'a plan carrying a malformed source flow property digest no longer matches its signed digest'
);

-- The private executor judges the snapshot's own shape before the signed digest: a snapshot that is
-- missing or malformed is refused on its own terms, not only as an unsigned document.
select is(
  (private.cmd_dataset_alias_plan_v2_guarded(
     jsonb_set((select request->'plan' from v2_wire), '{source_evidence}',
       ((select request->'plan' from v2_wire) #> '{source_evidence}') - 'source_flowproperty')
   )->>'code'),
  'ALIAS_V2_PLAN_INVALID',
  'the private executor refuses a plan whose source evidence omits the source flow property snapshot'
);
select is(
  (private.cmd_dataset_alias_plan_v2_guarded(
     jsonb_set((select request->'plan' from v2_wire), '{source_evidence,source_flowproperty,sha256}', '"not-a-digest"'::jsonb)
   )->>'code'),
  'ALIAS_V2_PLAN_INVALID',
  'the private executor refuses a malformed source flow property digest'
);

-- A plan edit breaks the plan/freeze/approval binding chain: the freeze is compared first.
select pg_temp.as_actor();
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded(
     jsonb_set((select request from v2_wire), '{plan,actions,0,expected_state_code}', '7'::jsonb)
   )->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_INVALID_PLAN',
  'a request whose plan body no longer matches its signed digest is refused at admission'
);

-- ================================================================================================
-- 2. The preflight: the rollback-only simulation and the 180-second window.
-- ================================================================================================
create temp table v2_preflight as
  select api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire)) as result;

select is((select result->>'ok' from v2_preflight), 'true', 'the reviewed request passes the protected preflight');
select is((select result->>'command' from v2_preflight), 'cmd_dataset_alias_execution_preflight_v2_guarded', 'the preflight reports its own command');
select is((select result->>'schema_version' from v2_preflight), 'dataset-alias-execution-preflight-proof.v2', 'the preflight proof is the versioned schema');
select is((select result->>'request_id' from v2_preflight), 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265', 'the proof is bound to the client request identity');
select is((select result->>'plan_sha256' from v2_preflight), '3ed37f87d621a03237a3a0d004bf00403b3fbba292beebf0ea5bafadb1e276d5', 'the proof carries the CLI plan digest');
select is((select result->>'operation_id' from v2_preflight), '3ed37f87d621a03237a3a0d004bf00403b3fbba292beebf0ea5bafadb1e276d5', 'the internal operation identity is the plan digest');
select is((select result->>'environment' from v2_preflight) || '/' || (select result->>'project_ref' from v2_preflight), 'production/qgzvkongdjqiiamzbbts', 'the proof is bound to the production server context');
select is((select result->'simulation'->>'rolled_back' from v2_preflight), 'true', 'the plan simulation rolled back');
select is((select result->'simulation'->>'plan_rows' from v2_preflight), '6', 'the simulation proves the plan row count');
select is((select result->'simulation'->>'plan_exchanges' from v2_preflight), '8', 'the simulation proves the plan exchange count');
select is((select result->'simulation'->>'alias_audits' from v2_preflight), '8', 'the simulation proves the plan audit topology');
select is((select result->'simulation'->>'derivative_targets' from v2_preflight), '6', 'the simulation proves the derivative target count');
select is(
  extract(epoch from ((select result->>'expires_at' from v2_preflight)::timestamptz
    - (select result->>'completed_at' from v2_preflight)::timestamptz))::integer,
  180,
  'the admission window is the preserved 180 seconds'
);
select is(
  (select result->>'gate_expectations_sha256' from v2_preflight) ~ '^[a-f0-9]{64}$',
  true,
  'the preflight issues the gate expectation set digest'
);
select is(
  (select count(*)::integer from jsonb_object_keys((select result->'gate_expectations' from v2_preflight))),
  3,
  'exactly the three gates carry expectations'
);

-- The simulation is rollback-only: no row, audit or derivative child survives it.
select is(
  (select count(*)::integer from public.flows where id::text like 'f10c0de0-0000-4000-8000-%'
     and json_ordered::jsonb #>> '{flowDataSet,flowProperties,flowProperty,0,referenceToFlowPropertyDataSet,@refObjectId}'
       = 'da11d28f-4db8-51eb-b3a9-8784b26771e6'),
  0,
  'the simulation wrote no flow change'
);
select is(
  (select count(*)::integer from util.dataset_alias_execution_v2_requests),
  0,
  'the simulation left no protected execution request'
);

-- Replaying the same approval identity cannot mint a second preflight.
select is(
  (api.cmd_dataset_alias_execution_preflight_v2_guarded((select request from v2_wire))->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_APPROVAL_ALREADY_USED',
  'the exact approval identity can be spent once'
);

-- ================================================================================================
-- 3. The three gates: order, window and stored receipts.
-- ================================================================================================
select is(
  (api.cmd_dataset_alias_execution_gate_v2_guarded('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
     (select result->>'preflight_token' from v2_preflight), 'execution_unused')->>'code'),
  'ALIAS_EXECUTION_GATE_ORDER_MISMATCH',
  'the unused-execution gate cannot be captured before the primary support gate'
);
select is(
  (api.cmd_dataset_alias_execution_gate_v2_guarded('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
     (select result->>'preflight_token' from v2_preflight), 'quiescence')->>'code'),
  'ALIAS_EXECUTION_GATE_INVALID_REQUEST',
  'a gate that is not one of the three reviewed names is refused'
);
select is(
  (api.cmd_dataset_alias_execution_gate_v2_guarded('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
     repeat('a', 64), 'primary_support_plan')->>'code'),
  'ALIAS_EXECUTION_PREFLIGHT_TOKEN_MISMATCH',
  'a gate with the wrong preflight token is refused'
);

create temp table v2_gate1 as
  select api.cmd_dataset_alias_execution_gate_v2_guarded('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
    (select result->>'preflight_token' from v2_preflight), 'primary_support_plan') as result;
create temp table v2_gate2 as
  select api.cmd_dataset_alias_execution_gate_v2_guarded('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
    (select result->>'preflight_token' from v2_preflight), 'execution_unused') as result;
create temp table v2_gate3 as
  select api.cmd_dataset_alias_execution_gate_v2_guarded('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
    (select result->>'preflight_token' from v2_preflight), 'derivative_quiescence') as result;

select is((select result->>'status' from v2_gate1), 'passed', 'the primary support gate passes');
select is((select result->>'status' from v2_gate2), 'passed', 'the execution-unused gate passes');
select is((select result->>'status' from v2_gate3), 'passed', 'the derivative-quiescence gate passes');
select is(
  (select result->>'expected_sha256' = result->>'observed_sha256' from v2_gate1),
  true,
  'the primary gate receipt proves the expected evidence was observed'
);
select is(
  (select count(*)::integer from util.dataset_alias_execution_v2_gate_receipts
    where actor_user_id = (select user_id from v2_actor)),
  3,
  'exactly three gate receipts are stored'
);

-- ================================================================================================
-- 4. Admission: one attempt, one dispatch, and the nonce-bound single execution.
-- ================================================================================================
select is(
  (api.cmd_dataset_alias_execution_admit_v2_guarded(pg_temp.admit_request(
     (select result->>'preflight_token' from v2_preflight),
     (select result->>'preflight_proof_sha256' from v2_preflight),
     jsonb_build_object('execution_unused', pg_temp.gate_projection((select result from v2_gate2)))))->>'code'),
  'ALIAS_EXECUTION_GATE_SET_MISMATCH',
  'an admission that does not carry the full gate set is refused'
);

create temp table v2_admit as
  select api.cmd_dataset_alias_execution_admit_v2_guarded(pg_temp.admit_request(
    (select result->>'preflight_token' from v2_preflight),
    (select result->>'preflight_proof_sha256' from v2_preflight),
    jsonb_build_object(
      'primary_support_plan', pg_temp.gate_projection((select result from v2_gate1)),
      'execution_unused', pg_temp.gate_projection((select result from v2_gate2)),
      'derivative_quiescence', pg_temp.gate_projection((select result from v2_gate3))))) as result;

select is(
  (select result->>'schema_version' from v2_admit),
  'dataset-alias-execution-admit-proof.v2',
  'the admission response carries its single proof schema name'
);
select is(
  (api.cmd_dataset_alias_execution_admit_v2_guarded(jsonb_build_object(
     'schema_version', 'dataset-alias-execution-admit-proof.v2',
     'request_id', 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265',
     'preflight_token', repeat('a', 64),
     'preflight_proof_sha256', repeat('a', 64),
     'gate_results', '{}'::jsonb))->>'code'),
  'ALIAS_EXECUTION_ADMISSION_INVALID_REQUEST',
  'the admission request keeps its own input schema name: the response name is not accepted as input'
);
select is((select result->>'ok' from v2_admit), 'true', 'the sealed admission is accepted');
select is((select result->>'status' from v2_admit), 'dispatched', 'admission queues exactly one dispatch');
select is((select result->>'attempt_count' from v2_admit) || '/' || (select result->>'dispatch_count' from v2_admit), '1/1', 'one attempt and one dispatch are consumed');
select is((select result->>'attempt_consumed' from v2_admit) || '/' || (select result->>'retry_allowed' from v2_admit), 'true/false', 'the single attempt is consumed without a retry');
select is(
  (select count(*)::integer from net.http_request_queue as queued
    join util.dataset_alias_execution_v2_requests as request on request.net_request_id = queued.id
   where request.id = 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid),
  1,
  'exactly one executor callback is queued'
);
select is(
  (api.cmd_dataset_alias_execution_admit_v2_guarded(pg_temp.admit_request(
     (select result->>'preflight_token' from v2_preflight),
     (select result->>'preflight_proof_sha256' from v2_preflight),
     '{}'::jsonb))->>'code'),
  'ALIAS_EXECUTION_ATTEMPT_ALREADY_CONSUMED',
  'the one-shot attempt cannot be admitted twice'
);
select pg_temp.as_actor('22222222-2222-4222-8222-222222222222');
select is(
  (api.cmd_dataset_alias_execution_read_v2('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid)->>'code'),
  'ALIAS_EXECUTION_REQUEST_NOT_FOUND',
  'a foreign actor cannot read the admitted execution'
);
select pg_temp.as_actor();

-- ================================================================================================
-- 5. The service-only executor, behind the dispatched nonce.
-- ================================================================================================
select is(
  (api.cmd_dataset_alias_execution_execute_v2('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid, repeat('0', 64))->>'code'),
  'SERVICE_ROLE_REQUIRED',
  'the executor refuses a non-service call'
);
select set_config('request.headers',
  jsonb_build_object(
    'apikey', util.project_secret_key(),
    'authorization', 'Bearer ' || util.project_secret_key())::text, true);
select is(
  (api.cmd_dataset_alias_execution_execute_v2('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
     (select reverse(convert_from(queued.body, 'UTF8')::jsonb->>'p_nonce')
      from net.http_request_queue as queued
      join util.dataset_alias_execution_v2_requests as request on request.net_request_id = queued.id
      where request.id = 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid))->>'code'),
  'ALIAS_EXECUTION_NONCE_MISMATCH',
  'the executor refuses a callback that is not bound to the dispatched nonce'
);

create temp table v2_execute as
  select api.cmd_dataset_alias_execution_execute_v2('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
    (select convert_from(queued.body, 'UTF8')::jsonb->>'p_nonce'
     from net.http_request_queue as queued
     join util.dataset_alias_execution_v2_requests as request on request.net_request_id = queued.id
     where request.id = 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid)) as result;

select is((select result->>'ok' from v2_execute), 'true', 'the nonce-bound callback executes the plan');
select is((select result->>'status' from v2_execute), 'derivatives_pending', 'the execution commits the primary and admits the derivative closure');
select is((select result->>'row_count' from v2_execute), '6', 'the executed row count is the plan count');
select is((select result->>'exchange_count' from v2_execute), '8', 'the executed exchange count is the plan count');
select is((select result->>'alias_audit_count' from v2_execute), '8', 'the executed audit topology is the plan count');
select is((select result->>'derivative_target_count' from v2_execute), '6', 'the derivative closure carries one target per changed row');
select is((select result->>'retry_allowed' from v2_execute), 'false', 'the executed attempt is not retryable');
select is(
  (api.cmd_dataset_alias_execution_execute_v2('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid,
     (select convert_from(queued.body, 'UTF8')::jsonb->>'p_nonce'
      from net.http_request_queue as queued
      join util.dataset_alias_execution_v2_requests as request on request.net_request_id = queued.id
      where request.id = 'fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid))->>'code'),
  'ALIAS_EXECUTION_ALREADY_STARTED',
  'a second callback against the executed attempt is refused'
);

-- The plan's own claims became the committed rows: each action holds exactly its desired payload.
select is((
  select count(*)::integer
  from jsonb_array_elements((select request->'plan'->'actions' from v2_wire)) as action
  where action->>'table' = 'flows'
    and (select flow.json_ordered::jsonb from public.flows as flow
         where flow.id = (action->>'id')::uuid
           and flow.version = action->>'version'
           and flow.state_code = 0) is distinct from action->'desired_json_ordered'
), 0, 'every committed flow holds exactly the payload the plan claimed');
select is((
  select count(*)::integer
  from jsonb_array_elements((select request->'plan'->'actions' from v2_wire)) as action
  where action->>'table' = 'processes'
    and (select process.json_ordered::jsonb from public.processes as process
         where process.id = (action->>'id')::uuid
           and process.version = action->>'version'
           and process.state_code = 0) is distinct from action->'desired_json_ordered'
), 0, 'every committed process holds exactly the payload the plan claimed');

-- The same plan submitted again is an exact replay: the stored proof, no writes and no new audits.
create temp table v2_audits_before as
  select count(*)::integer as audits from private.command_audit_log;
select pg_temp.as_actor();
select is(
  (private.cmd_dataset_alias_plan_v2_guarded((select request->'plan' from v2_wire))->>'code'),
  'ALIAS_V2_PLAN_REPLAYED',
  'the applied plan replays as the stored proof under the same identity'
);
select is(
  (select count(*)::integer from private.command_audit_log),
  (select audits from v2_audits_before),
  'an exact plan replay writes no audit row'
);

-- ================================================================================================
-- 6. The terminal read: the live closure proof over the committed rows.
-- ================================================================================================
create temp table v2_read as
  select api.cmd_dataset_alias_execution_read_v2('fcfbc113-8d7e-575c-a7f3-ba5abfbf2265'::uuid) as result;

select is(
  (select result->'terminal_proof' is not distinct from 'null'::jsonb from v2_read),
  true,
  'a pending execution carries a null terminal proof (never a fabricated observation)'
);
select is((select result->>'ok' from v2_read), 'true', 'the terminal read succeeds');
select is((select result->>'status' from v2_read), 'pending', 'the read reports the derivative closure as pending, never a completed run');
select is((select result->>'execution_status' from v2_read), 'derivatives_pending', 'the execution status is the committed primary');
select is((select result->>'retry_allowed' from v2_read), 'false', 'the read never offers a retry');
select is((select result->'primary_readback'->>'live_closure_proof' from v2_read), 'true', 'the read proves the live primary closure');
select is((select result->'primary_readback'->>'row_count' from v2_read), '6', 'the live closure counts the plan rows');
select is((select result->'primary_readback'->>'exchange_count' from v2_read), '8', 'the live closure counts the plan exchanges');
select is((select result->'primary_readback'->>'alias_audit_count' from v2_read), '8', 'the live closure counts the plan-derived audit topology');
select is((select result->'primary_readback'->'closure'->>'invalid_action_count' from v2_read), '0', 'no action of the closure is invalid');
select is((select result->>'plan_request_sha256' from v2_read), (select result->>'plan_request_sha256' from v2_execute), 'the read echoes the executing plan request digest');

select * from finish();
rollback;
